import React from 'react';

import {
  SliderHandlePoint,
  SliderPreviewHandle,
  SliderPreviewProgressBar,
  SliderPreviewStartDot,
  SliderProgressBar,
  SliderStartDotPoint,
} from '../../TimePeriodSelector.styles';
import type { SliderPositions } from '../../utils';

interface SliderTrackLayersProps {
  /** Committed (applied) slider state */
  positions: SliderPositions;
  /** Preview (drag ghost) state — null when not dragging or no valid preview */
  preview: SliderPositions | null;
  showHandle?: boolean;
}

export function SliderTrackLayers({
  positions: p,
  preview: pp,
  showHandle = true,
}: Readonly<SliderTrackLayersProps>) {
  if (pp === null) {
    return (
      <>
        {p.showProgress && (
          <SliderProgressBar
            data-testid="time-period-slider-progress"
            style={{ left: `${p.progressLeft}%`, width: `${p.progressWidth}%` }}
          />
        )}
        {p.startDotLeft !== null && (
          <SliderStartDotPoint
            data-testid="time-period-slider-start"
            style={{ left: `${p.startDotLeft}%` }}
          />
        )}
        {showHandle && (
          <SliderHandlePoint
            data-testid="time-period-slider-handle"
            style={{ left: `${p.handleLeft}%` }}
          />
        )}
      </>
    );
  }

  return (
    <>
      {pp.showProgress && (
        <SliderPreviewProgressBar
          data-testid="time-period-slider-preview-progress"
          style={{
            left: `${pp.progressLeft}%`,
            width: `${pp.progressWidth}%`,
          }}
        />
      )}
      {pp.startDotLeft !== null && (
        <SliderPreviewStartDot
          data-testid="time-period-slider-preview-start"
          style={{ left: `${pp.startDotLeft}%` }}
        />
      )}
      {showHandle && (
        <SliderPreviewHandle
          data-testid="time-period-slider-preview-handle"
          style={{ left: `${pp.handleLeft}%` }}
        />
      )}
    </>
  );
}
